package com.gymmind.workout.infrastructure.persistence; import com.gymmind.workout.domain.model.WorkoutSet; import com.gymmind.workout.domain.repository.WorkoutSetRepository; import org.springframework.stereotype.Repository; @Repository class JpaWorkoutSetRepository implements WorkoutSetRepository { private final SpringDataWorkoutSetRepository delegate; JpaWorkoutSetRepository(SpringDataWorkoutSetRepository d){delegate=d;} public WorkoutSet save(WorkoutSet s){return delegate.save(s);} }
